  INSERT INTO lessons(chapter_id,prompt_character_id,learner_character_id,title,title_translation,description,description_translation,lesson_type,storyline_key,storyline_order,difficulty,estimated_duration_sec,sort_order,status,metadata) VALUES(v_chapter,v_c_ben,v_c_lena,'Die direkte Abfahrt','حرکت مستقیم','Der direkte Zug fährt ab, und Lena und Ben können sich nach den Problemen endlich entspannen.','قطار مستقیم حرکت می‌کند و لنا و بن پس از مشکلات بالاخره می‌توانند آسوده شوند.','story','lena-ben-b1-travel-problems',17,52,180,1,'validated','{"relationship":"friends","context":"arrival","cefr":"B1","storyArc":"arrive-after-problems"}');
