  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_1,v_c_ben,1,'character','Der Zug ist pünktlich vom Bahnsteig abgefahren.','قطار سروقت از سکو حرکت کرده است.',52,NULL,NULL,NULL,NULL,'[{"surface":"Der","lemma":"der","translation":"حرف تعریف","partOfSpeech":"article"},{"surface":"Zug","lemma":"Zug","translation":"قطار","partOfSpeech":"noun"},{"surface":"ist","lemma":"sein","translation":"بودن","partOfSpeech":"verb"},{"surface":"pünktlich","lemma":"pünktlich","translation":"سروقت","partOfSpeech":"adjective"},{"surface":"vom","lemma":"von","translation":"از / از سمت","partOfSpeech":"preposition"},{"surface":"Bahnsteig","lemma":"Bahnsteig","translation":"سکوی قطار","partOfSpeech":"noun"},{"surface":"abgefahren","lemma":"abfahren","translation":"حرکت کردن","partOfSpeech":"verb","suffix":"."}]','Eine Reise abschließen','برای روایت پایان سفر از Perfekt، Präteritum و واژه‌هایی مانند endlich، doch و am Ende استفاده می‌شود.','{"focus":"travel_arrival_narration","structures":["Perfekt arrival","am Ende","separable arrival verbs"]}','{"cefr":"B1","course":"de-fa","series":100}');
  SET v_t_1=LAST_INSERT_ID();
