  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_2,v_c_ben,1,'character','Draußen wird es langsam dunkel.','بیرون کم‌کم تاریک می‌شود.',52,NULL,NULL,NULL,NULL,'[{"surface":"Draußen","lemma":"draußen","translation":"بیرون","partOfSpeech":"adverb"},{"surface":"wird","lemma":"werden","translation":"شدن / خواهد","partOfSpeech":"verb"},{"surface":"es","lemma":"es","translation":"آن / این / ضمیر خنثی","partOfSpeech":"pronoun"},{"surface":"langsam","lemma":"langsam","translation":"آهسته","partOfSpeech":"adjective"},{"surface":"dunkel","lemma":"dunkel","translation":"تاریک","partOfSpeech":"adjective","suffix":"."}]','Eine Reise abschließen','برای روایت پایان سفر از Perfekt، Präteritum و واژه‌هایی مانند endlich، doch و am Ende استفاده می‌شود.','{"focus":"travel_arrival_narration","structures":["Perfekt arrival","am Ende","separable arrival verbs"]}','{"cefr":"B1","course":"de-fa","series":100}');
  SET v_t_7=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_2,v_c_lena,2,'learner','Trotzdem fühle ich mich jetzt entspannter.','با این حال حالا آرامش بیشتری دارم.',52,NULL,NULL,'trotzdem fühle ich mich jetzt entspannter',NULL,'[{"surface":"Trotzdem","lemma":"trotzdem","translation":"با این حال","partOfSpeech":"adverb"},{"surface":"fühle","lemma":"sich fühlen","translation":"احساس کردن","partOfSpeech":"verb"},{"surface":"ich","lemma":"ich","translation":"من","partOfSpeech":"pronoun"},{"surface":"mich","lemma":"ich","translation":"من","partOfSpeech":"pronoun"},{"surface":"jetzt","lemma":"jetzt","translation":"حالا / اکنون","partOfSpeech":"adverb"},{"surface":"entspannter","lemma":"entspannt","translation":"آرام تر","partOfSpeech":"adjective","suffix":"."}]','Eine Reise abschließen','برای روایت پایان سفر از Perfekt، Präteritum و واژه‌هایی مانند endlich، doch و am Ende استفاده می‌شود.','{"focus":"travel_arrival_narration","structures":["Perfekt arrival","am Ende","separable arrival verbs"]}','{"cefr":"B1","course":"de-fa","series":100}');
