  INSERT INTO lessons(chapter_id,prompt_character_id,learner_character_id,title,title_translation,description,description_translation,lesson_type,storyline_key,storyline_order,difficulty,estimated_duration_sec,sort_order,status,metadata) VALUES(v_chapter,v_c_ben,v_c_lena,'Vor dem Bahnhof','جلوی ایستگاه','Lena und Ben blicken auf die schwierige Reise zurück und gehen erleichtert zum Hotel.','لنا و بن سفر دشوار را مرور می‌کنند و با خیال راحت به هتل می‌روند.','story','lena-ben-b1-travel-problems',20,52,180,4,'validated','{"relationship":"friends","context":"arrival","cefr":"B1","storyArc":"arrive-after-problems"}');
