  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_4,v_c_ben,5,'character','Morgen erzählen wir den anderen von der Fahrt.','فردا ماجرای سفر را برای بقیه تعریف می‌کنیم.',52,NULL,NULL,NULL,NULL,'[{"surface":"Morgen","lemma":"morgen","translation":"فردا","partOfSpeech":"adverb"},{"surface":"erzählen","lemma":"erzählen","translation":"تعریف کردن","partOfSpeech":"verb"},{"surface":"wir","lemma":"wir","translation":"ما","partOfSpeech":"pronoun"},{"surface":"den","lemma":"der","translation":"حرف تعریف","partOfSpeech":"article"},{"surface":"anderen","lemma":"andere","translation":"دیگران","partOfSpeech":"pronoun"},{"surface":"von","lemma":"von","translation":"از / از سمت","partOfSpeech":"preposition"},{"surface":"der","lemma":"der","translation":"حرف تعریف","partOfSpeech":"article"},{"surface":"Fahrt","lemma":"Fahrt","translation":"سفر / مسیر","partOfSpeech":"noun","suffix":"."}]','Eine Reise abschließen','برای روایت پایان سفر از Perfekt، Präteritum و واژه‌هایی مانند endlich، doch و am Ende استفاده می‌شود.','{"focus":"travel_arrival_narration","structures":["Perfekt arrival","am Ende","separable arrival verbs"]}','{"cefr":"B1","course":"de-fa","series":100}');
  SET v_t_23=LAST_INSERT_ID();
